 const gap=fresh.length<2?'<p class="gap-single">סניף אחד בלבד עם מחיר עדכני</p>':span===0?`<p class="gap-single">כל ${fresh.length} הסניפים באותו מחיר</p>`:`<div class="gap"><div class="gap-bar">${fresh.map((o,i)=>`<span class="gap-tick ${i===0?'is-low':o.cents===high.cents?'is-high':''}" style="--at:${((o.cents-low.cents)/span).toFixed(4)}"></span>`).join('')}</div><div class="gap-legend"><span class="low">הזול <b>${money(low.cents)} ₪</b></span><span>${fresh.length} סניפים</span><span class="high">היקר <b>${money(high.cents)} ₪</b></span></div></div>`;
