async function render(append=false){const seq=++requestId;if(!append){offset=0;$('products').setAttribute('aria-busy','true');if(!$('products').querySelector('.product:not(.skeleton)'))$('products').innerHTML=skeleton();}try{if(!selected.length){$('products').innerHTML='<div class="no-results"><strong>מתחילים באזור שבו קונים</strong><br>בחרו עיר או יישוב, ואז נוסיף את הסניפים הרלוונטיים להשוואה.</div>';$('resultCount').textContent='ממתין לבחירת אזור';$('loadMore').hidden=true;return;}const data=await api('/api/products?'+new URLSearchParams({q:$('search').value,stores:storeQuery(),sort:$('sort').value,promos:promos?'1':'0',offset:String(offset)}));if(seq!==requestId)return;total=data.total;data.products.forEach(p=>{cache.set(p.id,p);names.set(p.id,p.name);outOfScope.delete(p.id);});$('resultCount').textContent=`${total.toLocaleString('he-IL')} מוצרים`;const content=data.products.map(card).join('');if(append)$('products').insertAdjacentHTML('beforeend',content);else $('products').innerHTML=content||'<div class="no-results">לא נמצאו מוצרים בנתונים של הסניפים שנבחרו.<br>אפשר לשנות את החיפוש או לבחור סניפים נוספים.</div>';offset+=data.products.length;$('loadMore').hidden=offset>=total;$('allNav').classList.toggle('nav-active',!promos);$('promoNav').classList.toggle('nav-active',promos);$('allNav').setAttribute('aria-pressed',String(!promos));$('promoNav').setAttribute('aria-pressed',String(promos));}catch(e){if(seq===requestId){$('products').innerHTML='<div class="no-results">לא ניתן לטעון מחירים. בדקו שהשרת המקומי פועל ונסו שוב.</div>';$('loadMore').hidden=true;}}finally{$('products').removeAttribute('aria-busy');}}
function promoMarkup(p){return `<div class="promo-detail"><strong>${esc(p.description)}</strong><p>תוקף: ${esc(date(p.start))} — ${esc(date(p.end))}<br>${p.club&&!/^0(?:\D|$)/.test(p.club)?`מועדון לפי קוד המקור: ${esc(p.club)} · `:''}${p.coupon?'נדרש קופון · ':''}כמות מינימלית במקור: ${esc(p.conditions.minQty||'לא צוינה')}${p.conditions.maxQty?' · עד '+esc(p.conditions.maxQty):''}<br>${esc(p.restrictions)}</p><small>תנאי המבצע מוצגים כפי שפורסמו; אינם מחושבים במחיר הרגיל או בסל.</small><a href="/api/source?file=${encodeURIComponent(p.sourceFile)}">קובץ המבצע המקורי ↓</a></div>`;}
function imageCredit(p){const im=p.image;if(!im?.url)return '';
 const link=(url,text)=>url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`:esc(text);
 return `<div class="image-credit"><img src="${esc(im.url)}" alt="תמונת ${esc(p.name)}" loading="lazy" decoding="async" referrerpolicy="no-referrer"><div><strong>תמונת המוצר</strong><p>מקור: ${im.sourcePage?link(im.sourcePage,im.source||'עמוד המקור'):esc(im.source||'לא צוין')}<br>ייחוס: ${esc(im.attribution||'לא צוין')}<br>רישיון: ${im.licenseUrl?link(im.licenseUrl,im.license||'תנאי הרישיון'):esc(im.license||'לא צוין')}<br>עודכן במקור: ${esc(date(im.updatedAt))} · נבדק אצלנו: ${esc(date(im.checkedAt))}</p></div></div>`;}
async function detail(id){$('detailContent').innerHTML='<p>טוען מחירים ומקורות…</p>';$('detail').showModal();try{const p=await api('/api/product?'+new URLSearchParams({id,stores:storeQuery()}));names.set(p.id,p.name);$('detailContent').innerHTML=`<div class="eyebrow">השוואה לפי ברקוד ${esc(p.barcode)}</div><h2>${esc(p.name)}</h2><p>${esc(p.brand)} · ${esc(p.size)}</p>${imageCredit(p)}${p.offers.map(o=>`<section class="offer-detail"><div class="detail-row"><div><strong>${esc(o.chainName)}</strong><div class="meta">${esc(o.storeName)} · ${esc(o.city)}</div></div><strong>${money(o.cents)} ₪</strong></div><p>תיאור במקור: ${esc(o.sourceName)} · ${esc(o.sourceSize)}<br>מחיר רגיל${o.stale?' · הקובץ ישן מ־48 שעות':''}<br>פורסם בקובץ: ${esc(date(o.sourcePublishedAt))}<br>שינוי המחיר לפי הרשת: ${esc(o.priceUpdatedAt)}<br>בדיקה אחרונה: ${esc(date(o.lastCheckedAt))}${o.unitPrice?`<br>מחיר ליחידת מידה במקור: ${esc(o.unitPrice)} ₪ / ${esc(o.unit)}`:''}</p><div class="source-links"><a href="${esc(o.sourceUrl)}" target="_blank" rel="noopener noreferrer">פורטל הרשת ↗</a><a href="/api/source?file=${encodeURIComponent(o.sourceFile)}">הורדת קובץ המקור ↓</a></div><div class="source-name">${esc(o.sourceFile)}</div>${o.promotions.map(promoMarkup).join('')}</section>`).join('')}<p>פרסום מחיר אינו אישור מלאי. המחירים מתייחסים לסניפים המצוינים בלבד.</p>`;}catch{$('detailContent').innerHTML='<p>לא ניתן לטעון את פרטי המוצר כרגע.</p>';}}
async function renderBasket(){const seq=++basketRequest;const items=Object.entries(basket).map(([id,quantity])=>({id,quantity}));const units=items.reduce((a,b)=>a+b.quantity,0);$('basketCount').textContent=units;dock(units);updateJourney();try{localStorage.setItem('salsal-live-basket',JSON.stringify(basket));const savedNames=Object.fromEntries(items.map(i=>[i.id,names.get(i.id)]).filter(([,name])=>name));localStorage.setItem('salsal-live-basket-names',JSON.stringify(savedNames));}catch{}if(selected.length)for(const item of items)if(!cache.has(item.id)){try{const p=await api('/api/product?'+new URLSearchParams({id:item.id,stores:storeQuery()}));cache.set(item.id,p);names.set(item.id,p.name);outOfScope.delete(item.id);}catch{outOfScope.add(item.id);}}if(seq!==basketRequest)return;$('basketItems').innerHTML=items.length?items.map(i=>`<div class="basket-item"><div class="basket-item-name"><strong>${esc(names.get(i.id)||cache.get(i.id)?.name||i.id)}</strong>${outOfScope.has(i.id)?'<small>חסר באזור שנבחר · לא הוחלף</small>':''}</div><div class="quantity"><button data-change="${esc(i.id)}" data-delta="-1" aria-label="הפחתת כמות">−</button><span>${i.quantity}</span><button data-change="${esc(i.id)}" data-delta="1" aria-label="הוספת כמות">+</button></div></div>`).join(''):'<div class="empty"><strong>מה קונים היום?</strong>חפשו מוצרים והוסיפו אותם לסל.<br>ההשוואה תתעדכן כאן אוטומטית.</div>';$('basketTotals').innerHTML=items.length&&selected.length?'<div class="total-heading">מחשב את הסל…</div>'+'<div class="sk sk-row"></div>'.repeat(Math.min(3,selected.length)):'';if(!items.length||!selected.length)return;try{const result=await api('/api/basket',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items,stores:selected})});if(seq!==basketRequest)return;const eligible=result.stores.filter(s=>s.complete&&!s.stale),best=eligible.length>1&&selected.every(id=>state.stores.some(s=>s.id===id))?Math.min(...eligible.map(s=>s.cents)):null;$('basketTotals').innerHTML='<div class="total-heading">סל לפי מחיר רגיל · לפני מבצעים</div>'+result.stores.map(s=>{const win=s.complete&&!s.stale&&s.cents===best,over=best!=null&&s.complete&&!s.stale&&s.cents>best?`<span class="delta">+${money(s.cents-best)} ₪</span>`:'';const missing=s.complete?'':`<details class="missing-products"><summary>חסרים ${s.missing.length} מוצרים · לא הוחלפו</summary><ul>${s.missing.map(name=>`<li>${esc(name)}</li>`).join('')}</ul></details>`;return `<div class="total-row ${win?'best':''}"><div>${win?'<span class="best-flag">הזול ביותר</span>':''}<strong>${esc(s.chainName)}</strong><div class="meta">${esc(s.name)}</div>${missing}${s.stale?'<small>נתוני מקור ישנים</small>':''}</div><div class="total-amount">${s.complete?money(s.cents)+' ₪':'—'}${over}</div></div>`;}).join('');const champion=result.stores.find(s=>s.complete&&!s.stale&&s.cents===best);dock(units,champion?`${champion.chainName} · ${money(champion.cents)} ₪`:'');}catch{$('basketTotals').textContent='חישוב הסל אינו זמין כרגע.';dock(units);}}
function change(id,delta){const off=delta>0?scopeMismatch():null;if(off){toast(`יש להחיל את הסניפים ב${off} לפני הוספה לסל`);return false;}if(delta>0&&Object.keys(basket).length>=100&&!basket[id]){toast('אפשר להשוות עד 100 מוצרים בסל');return false;}basket[id]=Math.min(99,(basket[id]||0)+delta);if(basket[id]<=0)delete basket[id];renderBasket();return true;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add&&change(b.dataset.add,1))toast('נוסף לסל');if(b.dataset.detail)detail(b.dataset.detail);if(b.dataset.change)change(b.dataset.change,Number(b.dataset.delta));if(b.dataset.store){$('branchPicker').open=true;draft=[...selected];renderDirectory();}if(b.id==='applyCity'){const ids=representativeIds();if(ids.length)applyStores(ids);else toast('אין סניפים מחוברים ביישוב הזה');}});let timer;$('search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>render(),220);};$('sort').onchange=()=>render();$('city').oninput=()=>{cityIndex=-1;$('clearCity').hidden=!$('city').value&&!selected.length;openCityMenu();if($('branchPicker').open)renderDirectory();};
$('city').onchange=()=>{const value=$('city').value.trim();if(value===appliedCity||applying)return;if(!value){applyStores([]);return;}if(cityRecord()){const ids=representativeIds();if(ids.length)applyStores(ids);}else renderScope();};$('city').onfocus=()=>openCityMenu();$('city').onblur=()=>setTimeout(closeCityMenu,120);$('city').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();moveCityMenu(1);}else if(e.key==='ArrowUp'){e.preventDefault();moveCityMenu(-1);}else if(e.key==='Enter'){if(cityIndex>=0&&cityMatches[cityIndex]){e.preventDefault();chooseCity(cityMatches[cityIndex].name);}else closeCityMenu();}else if(e.key==='Escape'&&!$('cityMenu').hidden){e.preventDefault();e.stopPropagation();closeCityMenu();}};$('cityMenu').onmousedown=e=>{const b=e.target.closest('[data-city]');if(!b)return;e.preventDefault();chooseCity(b.dataset.city);};$('cityMenu').onclick=e=>{e.preventDefault();e.stopPropagation();};$('chainFilter').onchange=renderDirectory;$('branchSearch').oninput=renderDirectory;
$('clearCity').onclick=async()=>{if(applying)return;$('city').value='';closeCityMenu();if(await applyStores([]))toast('בחירת האזור בוטלה');};
$('branchList').onchange=e=>{const id=e.target.dataset.branch;if(!id)return;if(e.target.checked){if(draft.length>=24){e.target.checked=false;toast('אפשר להשוות עד 24 סניפים בכל פעם');return;}draft.push(id);}else draft=draft.filter(x=>x!==id);renderDirectory();$('branchList').querySelector('[data-branch="'+CSS.escape(id)+'"]')?.focus();};
$('representativeStores').onclick=()=>{draft=representativeIds();renderDirectory();};$('clearDraft').onclick=()=>{draft=[];renderDirectory();};$('applyBranches').onclick=applySelection;$('branchPicker').ontoggle=()=>{if($('branchPicker').open)renderDirectory();};
$('loadMore').onclick=()=>render(true);$('allNav').onclick=()=>{promos=false;render();};$('promoNav').onclick=()=>{promos=true;render();};$('clear').onclick=()=>{basket={};renderBasket();};document.querySelector('.close').onclick=()=>$('detail').close();$('sourcesBtn').onclick=()=>{$('detailContent').innerHTML=`<h2>מאיפה המחירים?</h2><div class="source-summary"><strong>ישירות מפרסומי הרשתות</strong><span>המידע אינו מועתק מאתר השוואה אחר. הוא נקרא מקובצי המחירים, המבצעים והסניפים שהקמעונאים מפרסמים לציבור מכוח חוק שקיפות המחירים.</span></div>${sourceDirectory()}<p>כל מחיר משויך לברקוד, לסניף ולקובץ מקור מסוים. במסך פרטי המוצר אפשר לראות מתי הקובץ פורסם ואף להוריד את הקובץ המקורי ששימש להשוואה.</p><p>השרת בודק קבצים חדשים כל 15 דקות, כל עוד הוא פועל והמחשב מחובר. הרשת קובעת מתי מתפרסם מידע חדש. תאריך שינוי מחיר יכול להיות ישן גם בקובץ חדש, אם המחיר עצמו לא השתנה.</p><p>הסל מחושב במחירים רגילים בלבד. מבצעי מועדון, כמות וקופון מוצגים בנפרד עם תוקף ותנאים, ואינם מחושבים אוטומטית.</p><p>מאגר החיפוש מכיל ${directory?.localities.length||0} יישובים מתוך רשימת היישובים הממשלתית, ו־${directory?.stores.length||0} סניפים מתוך קובצי הרשתות. עצם הופעת יישוב בחיפוש אינה מעידה שיש בו סניף מחובר.</p><div class="source-links"><a href="https://www.gov.il/he/pages/cpfta_prices_regulations" target="_blank" rel="noopener noreferrer">רשימת הקמעונאים של הרשות להגנת הצרכן ↗</a><a href="https://main.knesset.gov.il/Activity/Legislation/Laws/pages/lawprimary.aspx?lawitemid=2001381" target="_blank" rel="noopener noreferrer">חוק קידום התחרות בענפי המזון והפארם ↗</a><a href="https://data.gov.il/dataset/citiesandsettelments" target="_blank" rel="noopener noreferrer">רשימת היישובים הממשלתית ↗</a></div>`;$('detail').showModal();};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('detail').open){e.preventDefault();$('search').focus();}});
function dock(count,best){$('basketDock').hidden=false;$('dockCount').textContent=count;$('dockText').textContent=best?`הזול ביותר · ${best}`:!selected.length&&count?'בחרו אזור להשוואת הסל':count?'שלב 3 · הצגת הסל':'שלב 3 · הסל ממתין למוצרים';}
function basketSheet(open,returnFocus=true){if(open&&!matchMedia('(max-width: 900px)').matches)return;document.body.classList.toggle('basket-open',open);$('basketBackdrop').hidden=!open;$('basketDock').setAttribute('aria-expanded',String(open));if(open){$('basket').setAttribute('role','dialog');$('basket').setAttribute('aria-modal','true');$('basket').focus();}else{$('basket').removeAttribute('role');$('basket').removeAttribute('aria-modal');if(returnFocus)$('basketDock').focus();}}
$('basketDock').onclick=()=>basketSheet(true);$('closeBasket').onclick=()=>basketSheet(false);$('basketBackdrop').onclick=()=>basketSheet(false);document.addEventListener('keydown',e=>{if(!document.body.classList.contains('basket-open'))return;if(e.key==='Escape'){basketSheet(false);return;}if(e.key==='Tab'){const focusable=[...$('basket').querySelectorAll('button,summary,[href],input,select,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled&&el.getClientRects().length),first=focusable[0],last=focusable.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});matchMedia('(max-width: 900px)').addEventListener('change',e=>{if(!e.matches&&document.body.classList.contains('basket-open'))basketSheet(false,false);});
let theme=null;try{const saved=localStorage.getItem('salsal-theme');if(saved==='dark'||saved==='light')theme=saved;}catch{}
function isDark(){return theme?theme==='dark':matchMedia('(prefers-color-scheme: dark)').matches;}
function applyTheme(){if(theme)document.documentElement.dataset.theme=theme;else delete document.documentElement.dataset.theme;$('themeToggle').setAttribute('aria-label',isDark()?'מעבר למצב בהיר':'מעבר למצב כהה');}
applyTheme();$('themeToggle').onclick=()=>{theme=isDark()?'light':'dark';applyTheme();try{localStorage.setItem('salsal-theme',theme);}catch{}};
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(!theme)applyTheme();});
async function init(){await status();await render();await renderBasket();}init();setInterval(status,10000);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'add_products_to_basket',description:'Add verified product IDs to the visible shopping list. Does not purchase; basket uses regular prices excluding promotions.',inputSchema:{type:'object',properties:{items:{type:'array',items:{type:'object',properties:{id:{type:'string'},quantity:{type:'integer',minimum:1,maximum:99}},required:['id','quantity']}}},required:['items']},execute:async input=>{if(!Array.isArray(input?.items)||input.items.length>100||!input.items.every(i=>typeof i.id==='string'&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=99))throw Error('Invalid items');if(new Set([...Object.keys(basket),...input.items.map(i=>i.id)]).size>100)throw Error('Basket limit is 100 products');const products=await Promise.all(input.items.map(i=>api('/api/product?'+new URLSearchParams({id:i.id,stores:storeQuery()}))));if(products.some(p=>p.weighted))throw Error('Weighted products are not supported in basket');for(let i=0;i<products.length;i++){cache.set(products[i].id,products[i]);names.set(products[i].id,products[i].name);}for(const i of input.items)basket[i.id]=Math.min(99,(basket[i.id]||0)+i.quantity);await renderBasket();return {basket};}})).catch(()=>{});}catch{}}
